/* @autogenerated */
/** Estado de una tarea larga o de uno de sus pasos, tal como lo informa el backend. */
export type TaskStatus = 'PENDING' | 'PROCESSING' | 'FINISHED' | 'FAILED';

export interface LongTask {
  uid: string;
  /** TIMEOUT lo genera el cliente cuando deja de sondear sin respuesta final. */
  detailStatus: TaskStatus | 'TIMEOUT';
  startTime?: Date;
  endTime?: Date;
  steps: LongTaskStep[];
}

export interface LongTaskStep {
  name: string;
  stepStatus: TaskStatus;
  startTime?: Date;
  endTime?: Date;
  totalItems: number;
  processedItems: number;
  oks: string[];
  warns: BatchResultErrorItem[];
  errors: BatchResultErrorItem[];
}

export interface BatchResultErrorItem {
  item: string;
  fails: MultipleErrorCodes[];
}

export interface MultipleErrorCodes {
  code: string;
  violation: string;
  wrongValues: { field: string; error: string; wrong: string }[];
}
